import {
  Mesh,
  PlaneGeometry,
  Object3D,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';
import { OrbitControls } from '@/primitives'; // placeholder import to satisfy alias usage, not used directly

export default function createNode(config, ctx) {
  // Load texture (synchronous via cached loader)
  const tex = ctx.textureLoader.load(config.assets?.imageUrl ?? '');

  // Determine aspect ratio from atlas region if provided
  const rect = config.atlas?.sourceRect ?? { width: 512, height: 320 };
  const aspect = rect.width / rect.height;

  // Create a plane geometry matching the aspect ratio
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Build a node material using the loaded texture
  const texNode = texture(tex);
  const material = new MeshBasicNodeMaterial({
    mapNode: texNode,
    toneMapped: false,
    transparent: true,
    depthWrite: false,
  });

  // Assemble mesh
  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    config.placement?.position?.[0] ?? 0,
    config.placement?.position?.[1] ?? -0.3,
    config.placement?.position?.[2] ?? 0
  );
  mesh.rotation.set(
    config.placement?.rotation?.[0] ?? 0,
    config.placement?.rotation?.[1] ?? 0,
    config.placement?.rotation?.[2] ?? 0
  );
  mesh.scale.set(
    config.placement?.scale?.[0] ?? 1,
    config.placement?.scale?.[1] ?? 1,
    config.placement?.scale?.[2] ?? 1
  );

  // Billboard: face the camera each frame
  mesh.onBeforeRender = function (_, __, camera) {
    mesh.quaternion.copy(camera.quaternion);
  };

  // Apply any cinematic primitives listed in the config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    }
  }

  // Event handlers placeholder (none defined)
  mesh.userData.handlers = {};

  // Track GSAP timelines for cleanup (none created here but structure kept)
  const _timelines = [];

  // Cleanup routine
  mesh.userData.cleanup = function () {
    geometry.dispose();
    material.dispose();
    if (tex?.dispose) tex.dispose();
    for (const tl of _timelines) {
      tl.kill();
    }
  };

  return mesh;
}
